WITH recent AS (SELECT DISTINCT serial_number FROM providers WHERE serial_number<>'' AND last_seen>pg_last_xact_replay_timestamp()-interval '10 minutes' ORDER BY serial_number LIMIT 20), paired AS (
 SELECT old.id AS oldest_id, fresh.id AS latest_id, old.last_seen AS oldest_seen, fresh.last_seen AS latest_seen FROM recent d
 CROSS JOIN LATERAL (SELECT id,last_seen FROM providers WHERE serial_number=d.serial_number ORDER BY last_seen ASC,id ASC LIMIT 1) old
 CROSS JOIN LATERAL (SELECT id,last_seen FROM providers WHERE serial_number=d.serial_number ORDER BY last_seen DESC,id DESC LIMIT 1) fresh
) SELECT json_build_object('kind','bounded_session_history','sample_limit',20,'sample_selection','first_20_recent_serials_lexical_not_random','devices_sampled',count(*),'different_oldest_latest_session',count(*) FILTER(WHERE oldest_id<>latest_id),'oldest_rep_missing',count(*) FILTER(WHERE o.provider_id IS NULL),'latest_rep_missing',count(*) FILTER(WHERE n.provider_id IS NULL),'latest_jobs_lower_than_oldest',count(*) FILTER(WHERE n.total_jobs<o.total_jobs),'latest_jobs_greater_than_oldest',count(*) FILTER(WHERE n.total_jobs>o.total_jobs),'oldest_session_min',min(oldest_seen),'latest_session_max',max(latest_seen)) FROM paired p LEFT JOIN provider_reputation o ON o.provider_id=p.oldest_id LEFT JOIN provider_reputation n ON n.provider_id=p.latest_id;
